#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;

#define SLEEP_MS 100
#define SLEEP_US 100000

/* Test k_sleep with K_FOREVER */
ZTEST(sleep_api, test_k_sleep_forever)
{
	k_sleep(K_FOREVER);
	/* This line should not be reached */
	zassert_unreachable("k_sleep(K_FOREVER) returned");
}

/* Test k_sleep with K_NO_WAIT */
ZTEST(sleep_api, test_k_sleep_timeout_0)
{
	int64_t start_time, end_time;

	start_time = k_uptime_get();
	k_sleep(K_NO_WAIT);
	end_time = k_uptime_get();

	zassert_true((end_time - start_time) < 1,
		     "k_sleep(K_NO_WAIT) slept for too long");
}

/* Test k_sleep with K_MSEC */
ZTEST(sleep_api, test_k_sleep_msec)
{
	int64_t start_time, end_time;
	k_timeout_t timeout = K_MSEC(SLEEP_MS);

	start_time = k_uptime_get();
	k_sleep(timeout);
	end_time = k_uptime_get();

	zassert_true((end_time - start_time) >= SLEEP_MS,
		     "k_sleep(K_MSEC) slept for less than expected");
	zassert_true((end_time - start_time) < (SLEEP_MS + 10),
		     "k_sleep(K_MSEC) slept for much longer than expected");
}

/* Test k_msleep */
ZTEST(sleep_api, test_k_msleep)
{
	int64_t start_time, end_time;

	start_time = k_uptime_get();
	k_msleep(SLEEP_MS);
	end_time = k_uptime_get();

	zassert_true((end_time - start_time) >= SLEEP_MS,
		     "k_msleep slept for less than expected");
	zassert_true((end_time - start_time) < (SLEEP_MS + 10),
		     "k_msleep slept for much longer than expected");
}

/* Test k_usleep */
ZTEST(sleep_api, test_k_usleep)
{
	int64_t start_time, end_time;

	start_time = k_uptime_get();
	k_usleep(SLEEP_US);
	end_time = k_uptime_get();

	zassert_true((end_time - start_time) >= (SLEEP_US / 1000),
		     "k_usleep slept for less than expected");
	zassert_true((end_time - start_time) < (SLEEP_US / 1000 + 10),
		     "k_usleep slept for much longer than expected");
}

/* Test k_busy_wait */
ZTEST(sleep_api, test_k_busy_wait)
{
	int64_t start_time, end_time;

	start_time = k_uptime_get();
	k_busy_wait(SLEEP_US);
	end_time = k_uptime_get();

	/* k_busy_wait is not guaranteed to be precise, but should be close */
	zassert_true((end_time - start_time) >= (SLEEP_US / 1000),
		     "k_busy_wait waited for less than expected");
	zassert_true((end_time - start_time) < (SLEEP_US / 1000 + 10),
		     "k_busy_wait waited for much longer than expected");
}

/* Test k_sleep with a negative timeout (should be treated as K_NO_WAIT) */
ZTEST(sleep_api, test_k_sleep_timeout_negative)
{
	int64_t start_time, end_time;

	start_time = k_uptime_get();
	k_sleep(K_MSEC(-100)); /* Negative timeout */
	end_time = k_uptime_get();

	zassert_true((end_time - start_time) < 1,
		     "k_sleep(negative timeout) slept for too long");
}

ZTEST_SUITE(sleep_api, NULL, NULL, NULL, NULL, NULL);

void test_main(void)
{
	ztest_run_test_suite(sleep_api);
}
